import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import {
  readReplay,
  REPLAY_MAX_ACTIONS,
  REPLAY_MAX_BYTES,
  REPLAY_VERSION,
  ReplayProblem,
} from '../src/game/replay.ts';
import { encodeSnapshot } from '../src/game/snapshot.ts';
import type { ReplayProblemKind } from '../src/game/replay.ts';

export const ReplayExit = { success: 0, failure: 1 } as const;
const MISSING_FILE = 'ENOENT';
const PROBLEMS = {
  [ReplayProblem.tooLarge]: `the file is larger than ${REPLAY_MAX_BYTES} bytes`,
  [ReplayProblem.malformedJson]: 'the file is not valid JSON',
  [ReplayProblem.format]: `it isn't a version ${REPLAY_VERSION} replay with exactly version, boardCode, actions and endMs`,
  [ReplayProblem.boardCode]: 'its board code is invalid',
  [ReplayProblem.actions]: `actions must be a list of at most ${REPLAY_MAX_ACTIONS}`,
  [ReplayProblem.endTime]: 'endMs must be a nonnegative safe integer',
  [ReplayProblem.action]: 'needs exactly atMs and index as nonnegative safe integers',
  [ReplayProblem.order]: 'comes before the previous action or after endMs',
  [ReplayProblem.index]: 'names a card outside the board',
} satisfies Record<ReplayProblemKind, string>;

function fail(file: string, reason: string): number {
  process.stderr.write(`Could not replay ${file}: ${reason}.\n`);
  return ReplayExit.failure;
}

function isMissing(error: unknown): boolean {
  return error instanceof Error && 'code' in error && error.code === MISSING_FILE;
}

// npm runs scripts from the package folder and records the caller's folder in INIT_CWD.
export async function runReplay(
  args: readonly string[],
  callerFolder = process.env.INIT_CWD ?? process.cwd(),
): Promise<number> {
  const [file] = args;
  if (!file || args.length !== 1) {
    process.stderr.write('Usage: npm run --silent replay -- PATH\n');
    return ReplayExit.failure;
  }
  let text: string;
  try {
    text = await readFile(resolve(callerFolder, file), 'utf8');
  } catch (error) {
    return fail(file, isMissing(error) ? 'the file does not exist' : "the file can't be read");
  }
  const result = readReplay(text);
  if ('state' in result) {
    process.stdout.write(`${encodeSnapshot(result.state)}\n`);
    return ReplayExit.success;
  }
  const reason = PROBLEMS[result.problem];
  return fail(file, result.action === undefined ? reason : `action ${result.action + 1} ${reason}`);
}
{
  "missing.json": "Could not replay missing.json: the file does not exist.\n",
  "broken.json": "Could not replay broken.json: the file is not valid JSON.\n",
  "rule.json": "Could not replay rule.json: action 1 names a card outside the board.\n"
}
import assert from 'node:assert/strict';
import { mkdtemp, mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { test, onTestFinished } from 'vitest';
import { REPLAY_VERSION } from '../src/game/replay.ts';
import { SNAPSHOT_VERSION } from '../src/game/snapshot.ts';
import { SelectionKind } from '../src/game/selection.ts';
import { EXAMPLE_CODE, SPEC_VECTOR } from '../src/game/game.fixture.ts';
import { ReplayExit } from './replay-cli.ts';

const CLI = fileURLToPath(new URL('./replay.ts', import.meta.url));
const TEST_ROOT = fileURLToPath(new URL('../.test-work/', import.meta.url));
const NPM_CLI = 'node_modules/npm/bin/npm-cli.js';
// Each test starts the CLI in child processes, which a busy machine slows far past vitest's default limit.
const CLI_TIMEOUT_MS = 60_000;

test('replay CLI prints a final snapshot and rejects invalid files and arguments', async () => {
  await mkdir(TEST_ROOT, { recursive: true });
  const directory = await mkdtemp(join(TEST_ROOT, 'replay-'));
  onTestFinished(() => rm(directory, { recursive: true, force: true }));
  const file = join(directory, 'replay.json');
  await writeFile(
    file,
    JSON.stringify({
      version: REPLAY_VERSION,
      boardCode: EXAMPLE_CODE,
      actions: [
        { atMs: 0, index: 0 },
        { atMs: 0, index: 11 },
      ],
      endMs: SPEC_VECTOR.mismatchMs,
    }),
  );
  const valid = spawnSync(process.execPath, [CLI, file], { encoding: 'utf8' });
  assert.equal(valid.status, ReplayExit.success);
  assert.equal(valid.stderr, '');
  const actual: unknown = JSON.parse(valid.stdout);
  assert.deepEqual(actual, {
    version: SNAPSHOT_VERSION,
    boardCode: EXAMPLE_CODE,
    matched: [0, 11],
    selection: { kind: SelectionKind.closed },
    moves: 1,
    elapsedMs: SPEC_VECTOR.mismatchMs,
    started: true,
  });
  await writeFile(file, '{');
  const invalid = spawnSync(process.execPath, [CLI, file], { encoding: 'utf8' });
  assert.equal(invalid.status, ReplayExit.failure);
  assert.equal(invalid.stdout, '');
  assert.ok(invalid.stderr.trim().length > 0);
  for (const args of [[], [file, file], [join(directory, 'missing.json')]]) {
    const rejected = spawnSync(process.execPath, [CLI, ...args], { encoding: 'utf8' });
    assert.equal(rejected.status, ReplayExit.failure);
    assert.equal(rejected.stdout, '');
    assert.ok(rejected.stderr.trim().length > 0);
  }
}, CLI_TIMEOUT_MS);

// A fresh shell has no INIT_CWD, so npm records the folder it starts in.
const CALLER_ENV = { ...process.env, INIT_CWD: undefined };

test('the replay command reads a relative path from the caller folder and names what failed', async () => {
  await mkdir(TEST_ROOT, { recursive: true });
  const directory = await mkdtemp(join(TEST_ROOT, 'replay-'));
  onTestFinished(() => rm(directory, { recursive: true, force: true }));
  const replay = { version: REPLAY_VERSION, boardCode: EXAMPLE_CODE, actions: [], endMs: 0 };
  await writeFile(join(directory, 'replay.json'), JSON.stringify(replay));
  await writeFile(join(directory, 'broken.json'), '{');
  const outside = { ...replay, actions: [{ atMs: 0, index: SPEC_VECTOR.sizes[0] ** 2 }] };
  await writeFile(join(directory, 'rule.json'), JSON.stringify(outside));
  // npm runs once, for the caller folder. The rejected files call the same CLI directly from that folder.
  const npm = process.env.npm_execpath ?? join(dirname(process.execPath), NPM_CLI);
  const valid = spawnSync(process.execPath, [npm, 'run', '--silent', 'replay', '--', 'replay.json'], {
    cwd: directory,
    env: CALLER_ENV,
    encoding: 'utf8',
  });
  assert.equal(
    valid.status,
    ReplayExit.success,
    `C14 relative path follows the caller folder: ${valid.stderr}`,
  );
  assert.equal(valid.stderr, '');
  assert.equal(JSON.parse(valid.stdout).boardCode, EXAMPLE_CODE);
  const messages: Record<string, string> = {};
  for (const file of ['missing.json', 'broken.json', 'rule.json']) {
    const rejected = spawnSync(process.execPath, [CLI, file], { cwd: directory, env: CALLER_ENV, encoding: 'utf8' });
    assert.equal(rejected.status, ReplayExit.failure);
    assert.equal(rejected.stdout, '');
    messages[file] = rejected.stderr;
  }
  const expected: unknown = JSON.parse(
    await readFile(new URL('./replay-messages.fixture.json', import.meta.url), 'utf8'),
  );
  assert.deepEqual(messages, expected);
}, CLI_TIMEOUT_MS);
import { runReplay } from './replay-cli.ts';

process.exitCode = await runReplay(process.argv.slice(2));
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { test } from 'vitest';
import { sourceFiles } from './source-files.ts';
import { isJsonObject } from '../src/game/saved-format.ts';

test('packages and lock use the reviewed exact versions and strict separate compiler projects', async () => {
  const pkg: unknown = JSON.parse(await readFile('package.json', 'utf8'));
  const expected: unknown = JSON.parse(
    await readFile(new URL('./package.fixture.json', import.meta.url), 'utf8'),
  );
  assert.ok(
    isJsonObject(pkg) &&
      isJsonObject(pkg.dependencies) &&
      isJsonObject(pkg.devDependencies) &&
      isJsonObject(expected),
  );
  const installed = { ...pkg.dependencies, ...pkg.devDependencies };
  assert.deepEqual(Object.keys(pkg.dependencies).sort(), ['react', 'react-dom']);
  for (const [name, version] of Object.entries(expected)) assert.equal(installed[name], version);
  const lock: unknown = JSON.parse(await readFile('package-lock.json', 'utf8'));
  assert.ok(isJsonObject(lock) && isJsonObject(lock.packages));
  const locked = lock.packages[''];
  assert.ok(isJsonObject(locked));
  assert.deepEqual(locked.dependencies, pkg.dependencies);
  assert.deepEqual(locked.devDependencies, pkg.devDependencies);
  assert.equal(pkg.type, 'module');
  const config: unknown = JSON.parse(await readFile('tsconfig.base.json', 'utf8'));
  assert.ok(isJsonObject(config) && isJsonObject(config.compilerOptions));
  for (const key of [
    'strict',
    'noUncheckedIndexedAccess',
    'exactOptionalPropertyTypes',
    'verbatimModuleSyntax',
    'erasableSyntaxOnly',
  ])
    assert.equal(config.compilerOptions[key], true);
  for (const project of ['app', 'node', 'e2e'])
    assert.ok(await readFile(`tsconfig.${project}.json`, 'utf8'));
  assert.ok(isJsonObject(pkg.scripts));
  assert.equal(
    pkg.scripts.typecheck,
    'tsc -p tsconfig.app.json && tsc -p tsconfig.node.json && tsc -p tsconfig.e2e.json',
    'T07 every compiler project',
  );
  assert.equal(pkg.scripts.test, 'vitest run', 'T02 Vitest runs unit tests');
});

test('authored TypeScript stays small, uses static ESM and rejects unsafe type escapes', async () => {
  const files = (await Promise.all(['src', 'scripts', 'tests', 'art'].map(sourceFiles))).flat();
  for (const file of files.filter((file) => /\.tsx?$/.test(file.path))) {
    assert.ok(file.text.trimEnd().split(/\r?\n/).length <= 200, file.path);
    assert.doesNotMatch(file.text, /@ts-(?:ignore|nocheck|expect-error)/);
    assert.doesNotMatch(
      file.text,
      /\bany\b|\bas\s+(?:[A-Z{]|unknown\b|number\b|string\b)|\bimport\s*\(|\brequire\s*\(/,
    );
  }
});

test('the game core has no browser effects and the shipped source has no audio or diagnostic entry', async () => {
  const files = await sourceFiles('src');
  const core = new Set(['deck.ts', 'game.ts', 'snapshot.ts', 'snapshot-selection.ts', 'replay.ts']);
  for (const file of files.filter((file) => !/\.(test|fixture)\./.test(file.path))) {
    assert.doesNotMatch(
      file.text,
      /AudioContext|new Audio\b|<audio|<canvas|fetch\(|XMLHttpRequest|window\.[a-zA-Z]*[Dd]eck/,
    );
    if (core.has(file.path.split(/[\\/]/).at(-1) ?? ''))
      assert.doesNotMatch(
        file.text,
        /\b(window|document|localStorage|performance|crypto|Date)\b|Math\.random/,
      );
    assert.doesNotMatch(file.text, /fixture|face-sheet|test-results/);
  }
});
import assert from 'node:assert/strict';
import { test } from 'vitest';
import { sourceFiles } from './source-files.ts';

const EXPORT = /^export (?:async )?(const|function|interface|type|class) (\w+)/gm;
const NAMED_IMPORT = /^import\s+(?:type\s+)?\{([^}]*)\} from/gm;
const CHECK = /^export function (\w+)\([^)]*\): (?:boolean|\w+ is )/gm;
const TEST_NAME = /\btest\(\s*(['`])(.*?)\1/gs;
const REQUIREMENT_ID = /\b[A-Z]\d{2}\b/;
const ENVIRONMENT = /process\.env(?:\.(\w+)|\[(\w+)\])/g;

async function typescriptFiles() {
  const files = (await Promise.all(['src', 'scripts', 'tests', 'art'].map(sourceFiles))).flat();
  return files.filter((file) => /\.tsx?$/.test(file.path));
}

// Keeps each imported name, without a type marker or local alias.
function importedNames(text: string): string[] {
  return [...text.matchAll(NAMED_IMPORT)].flatMap((match) =>
    (match[1] ?? '').split(',').map((name) => name.replace(/\btype\s+|\s+as\s+\w+/g, '').trim()),
  );
}

test('every export has an importer and each exported value has one owner', async () => {
  const files = await typescriptFiles();
  const imported = new Set(files.flatMap((file) => importedNames(file.text)));
  const owners = new Map<string, string>();
  for (const file of files)
    for (const [, kind, name = ''] of file.text.matchAll(EXPORT)) {
      assert.ok(imported.has(name), `${file.path} exports ${name} that nothing imports`);
      if (kind !== 'const') continue;
      assert.equal(owners.get(name), undefined, `${name} is exported by one owner`);
      owners.set(name, file.path);
    }
});

test('exported yes or no checks are named as questions', async () => {
  for (const file of await typescriptFiles())
    for (const [, name = ''] of file.text.matchAll(CHECK))
      assert.match(name, /^(?:is|has)[A-Z]/, `${file.path} names its check ${name}`);
});

test('test names describe behavior without requirement IDs', async () => {
  const files = await typescriptFiles();
  for (const file of files.filter((file) => /\.test\.ts$/.test(file.path)))
    for (const [, , name = ''] of file.text.matchAll(TEST_NAME))
      assert.doesNotMatch(name, REQUIREMENT_ID, `${file.path} test name ${name}`);
});

test('source reads only the environment its command and test runners need', async () => {
  const reads = (await typescriptFiles()).flatMap((file) =>
    [...file.text.matchAll(ENVIRONMENT)].map((match) => `${file.path}:${match[1] ?? match[2]}`),
  );
  const runners = [
    'scripts/replay-cli.ts:INIT_CWD',
    'scripts/replay.test.ts:npm_execpath',
    'tests/browser-test.ts:EXECUTABLE_ENV',
    'tests/browser-test.ts:NAMED_COMBINATION_ENV',
    'tests/browser-test.ts:NPM_AGENT_ENV',
    'tests/browser-test.ts:TEMP',
    'tests/browser-test.ts:TMP',
  ];
  assert.deepEqual([...new Set(reads.map((read) => read.replaceAll('\\', '/')))].sort(), runners);
});
import { readdir, readFile } from 'node:fs/promises';
import { join } from 'node:path';

export async function sourceFiles(
  folder: string,
): Promise<readonly { path: string; text: string }[]> {
  const result: { path: string; text: string }[] = [];
  for (const entry of await readdir(folder, { withFileTypes: true })) {
    const path = join(folder, entry.name);
    if (entry.isDirectory()) result.push(...(await sourceFiles(path)));
    else if (entry.isFile()) result.push({ path, text: await readFile(path, 'utf8') });
    else throw new Error('Source contains a link or special file.');
  }
  return result;
}
